39: StringUtils::guessEncoding(zxing::byte* bytes, int length,
40:                            Hashtable const& hints) {
41:   Hashtable::const_iterator i = hints.find(DecodeHints::CHARACTER_SET);
42:   if (i != hints.end()) {
43:     return i->second;
44:   }
45:   typedef bool boolean;
46:   // For now, merely tries to distinguish ISO-8859-1, UTF-8 and Shift_JIS,
47:   // which should be by far the most common encodings.
48:   boolean canBeISO88591 = true;
49:   boolean canBeShiftJIS = true;
50:   boolean canBeUTF8 = true;
51:   int utf8BytesLeft = 0;
52:   //int utf8LowChars = 0;
53:   int utf2BytesChars = 0;
54:   int utf3BytesChars = 0;
55:   int utf4BytesChars = 0;
56:   int sjisBytesLeft = 0;
57:   //int sjisLowChars = 0;
58:   int sjisKatakanaChars = 0;
59:   //int sjisDoubleBytesChars = 0;
